--
-- Table structure for table `lancamentos`
--

DROP TABLE IF EXISTS `lancamentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lancamentos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `empresa_id` int(11) NOT NULL,
  `data_evento` date NOT NULL,
  `data_vencimento` date NOT NULL,
  `data_pagamento` date DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `entidade_id` int(11) NOT NULL,
  `fluxo_conta_id` int(11) NOT NULL,
  `conta_banco_id` int(11) NOT NULL,
  `valor_real` decimal(15,2) NOT NULL,
  `valor_pago` decimal(15,2) DEFAULT NULL,
  `valor_imposto` decimal(15,2) DEFAULT NULL,
  `valor_outros_custos` decimal(15,2) DEFAULT NULL,
  `numero_documento` varchar(50) DEFAULT NULL,
  `observacoes` text DEFAULT NULL,
  `referencia_banco` varchar(100) DEFAULT NULL,
  `fonte` varchar(50) DEFAULT NULL,
  `criado_em` datetime DEFAULT NULL,
  `atualizado_em` datetime DEFAULT NULL,
